        sb.append(");\n}\n\nasync function refreshFileManagerUI() {\n  try {\n    const projects = PM.list();\n    const sizeBytes = PM.estimateSize();\n\n    // Текущий проект\n    const cn = $('fm_currentName');\n    const cm = $('fm_currentMeta');\n    if (currentProjectId) {\n      const proj = projects.find(p => p.id === currentProjectId);\n      if (proj) {\n        cn.textContent = proj.name || 'Без названия';\n        const d = new Date(proj.updatedAt || Date.now());\n        cm.textContent = 'Изменён: ' + d.toLocaleString();\n      } else {\n        cn.textContent = state.project.name || 'Текущий';\n        cm.textContent = 'Не сохранён';\n      }\n    } else {\n      cn.textContent = state.project.name || 'Текущий';\n      cm.textContent = 'Не сохранён';\n    }\n\n    // Список\n    const list = $('fm_projectList');\n    const empty = $('fm_empty');\n    const count = $('fm_count');\n    count.textContent = projects.length;\n\n    if (projects.length === 0) {\n      list.innerHTML = '';\n      empty.style.display = 'block';\n    } else {\n      empty.style.display = 'none';\n      list.innerHTML = projects.map(p => {\n        const isCurrent = p.id === currentProjectId;\n        const date = p.updatedAt ? new Date(p.updatedAt).toLocaleString() : '—';\n        return `\n          <div class=\"card-item ${isCurrent ? 'current' : ''}\">\n            <div style=\"font-weight:600; font-size:13px; margin-bottom:4px; word-break:break-word;\">\n              ${isCurrent ? '<span style=\"color:var(--ok)\">●</span> ' : ''}${escapeHTML(p.name || 'Без названия')}\n            </div>\n            <div style=\"font-size:11px; color:var(--muted); margin-bottom:8px;\">\n              ${date}\n            </div>\n            <div style=\"display:grid; grid-template-columns:1fr 1fr 1fr; gap:4px;\">\n              <button class=\"btn sm\" data-action=\"open\" data-id=\"${p.id}\" ${isCurrent ? 'disabled' : ''}>Открыть</button>\n              <button class=\"btn sm\" data-action=\"export\" data-id=\"${p.id}\">Экспорт</button>\n              <button class=\"btn sm danger\" data-action=\"delete\" data-id=\"${p.id}\">Удалить</button>\n            </div>\n          </div>\n        `;\n      }).join('');\n\n      // Навешиваем обработчики\n      list.querySelectorAll('[data-action]').forEach(btn => {\n        btn.addEventListener('click', () => {\n          const action = btn.dataset.action;\n          const id = btn.dataset.id;\n          if (action === 'open') openProject(id);\n          else if (action === 'export') exportProject(id);\n          else if (action === 'delete') deleteProject(id);\n        });\n      });\n    }\n\n    // Инфо о хранилище\n    const kb = (sizeBytes / 1024).toFixed(1);\n    $('fm_storageInfo').textContent =\n      `Тип: ${STORAGE.label}\\nИспользовано: ${kb} КБ\\nПроектов: ${projects.length}`;\n    $('fm_storageInfo').className = 'hint ' + (STORAGE.type === 'local' ? 'ok' : 'warn');\n    $('fm_storageInfo').style.whiteSpace = 'pre-line';\n  } catch (e) {\n    console.warn('refreshFileManagerUI error', e);\n  }\n}\n\n$('fm_saveNow').addEventListener('click', ");
