        sb.append("'] = `<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n${perms.join('\\n')}\n    <application\n        android:label=\"${escapeAttr(name)}\"\n        android:icon=\"@mipmap/ic_launcher\"\n        android:roundIcon=\"@mipmap/ic_launcher_round\"\n        android:usesCleartextTraffic=\"true\"\n        android:hardwareAccelerated=\"true\"\n        android:theme=\"@style/Theme.AppCompat.NoActionBar\">\n        <activity\n            android:name=\".MainActivity\"\n            android:configChanges=\"orientation|screenSize|keyboardHidden\"\n            android:exported=\"true\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n    </application>\n</manifest>`;\n\n  files[`app/src/main/java/${pkgPath}/MainActivity.java`] = `package ${pkg};\n\nimport android.content.ActivityNotFoundException;\nimport android.content.Intent;\nimport android.net.Uri;\nimport android.os.Bundle;\nimport android.webkit.PermissionRequest;\nimport android.webkit.ValueCallback;\nimport android.webkit.WebChromeClient;\nimport android.webkit.WebView;\nimport android.webkit.WebViewClient;\nimport androidx.appcompat.app.AppCompatActivity;\n\npublic class MainActivity extends AppCompatActivity {\n\n    private static final int FILE_CHOOSER_REQUEST = 1001;\n    private ValueCallback<Uri[]> filePathCallback;\n\n${htmlConstantCode}\n\n    @Override\n    protected void onActivityResult(int requestCode, int resultCode, Intent data) {\n        super.onActivityResult(requestCode, resultCode, data);\n        if (requestCode == FILE_CHOOSER_REQUEST) {\n            if (filePathCallback == null) return;\n            Uri[] results = null;\n            if (resultCode == RESULT_OK && data != null) {\n                if (data.getClipData() != null) {\n                    int count = data.getClipData().getItemCount();\n                    results = new Uri[count];\n                    for (int i = 0; i < count; i++) {\n                        results[i] = data.getClipData().getItemAt(i).getUri();\n                    }\n                } else if (data.getData() != null) {\n                    results = new Uri[]{ data.getData() };\n                }\n            }\n            filePathCallback.onReceiveValue(results);\n            filePathCallback = null;\n        }\n    }\n}\n`;\n\n  const iconSizes = {\n    'mipmap-mdpi': 48, 'mipmap-hdpi': 72, 'mipmap-xhdpi': 96,\n    'mipmap-xxhdpi': 144, 'mipmap-xxxhdpi': 192,\n  };\n\n  for (const [dir, size] of Object.entries(iconSizes)) {\n    let dataUrl;\n    if (state.project.iconDataUrl) {\n      dataUrl = await resizeIcon(state.project.iconDataUrl, size);\n    } else {\n      dataUrl = await generatePlainIcon(size, state.project.iconBg, name);\n    }\n    const base64 = dataUrl.split(',')[1];\n    const binary = atob(base64);\n    const bytes = new Uint8Array(binary.length);\n    for (let i = 0; i < binary.length;");
        sb.append(" i++) bytes[i] = binary.charCodeAt(i);\n    files[`app/src/main/res/${dir}/ic_launcher.png`] = bytes;\n    files[`app/src/main/res/${dir}/ic_launcher_round.png`] = bytes;\n  }\n\n  files['app/src/main/res/values/styles.xml'] = `<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <style name=\"Theme.AppCompat.NoActionBar.Custom\" parent=\"Theme.AppCompat.NoActionBar\">\n        <item name=\"android:statusBarColor\">${state.project.statusBarColor}</item>\n    </style>\n</resources>`;\n\n  files['.github/workflows/build.yml'] = `name: Build APK\n\non:\n  push:\n    branches: [ main ]\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  build:\n    runs-on: ubuntu-22.04\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v5\n        with:\n          distribution: 'temurin'\n          java-version: '17'\n      - uses: android-actions/setup-android@v4\n      - name: Install Gradle 8.2\n        run: |\n          wget -q https://services.gradle.org/distributions/gradle-8.2-bin.zip\n          unzip -q gradle-8.2-bin.zip -d /opt\n          echo \"/opt/gradle-8.2/bin\" >> \\$GITHUB_PATH\n      - name: Generate Gradle wrapper\n        run: gradle wrapper --gradle-version 8.2 --distribution-type bin\n      - name: Prepare build environment\n        run: |\n          echo \"sdk.dir=\\${ANDROID_SDK_ROOT}\" > local.properties\n          mkdir -p ~/.android\n          chmod 755 ~/.android\n          chmod +x gradlew\n      - name: Build Debug APK\n        run: ./gradlew assembleDebug --stacktrace --no-daemon\n      - name: Upload APK\n        if: success()\n        uses: actions/upload-artifact@v4\n        with:\n          name: app-debug\n          path: app/build/outputs/apk/debug/app-debug.apk\n          if-no-files-found: error\n          retention-days: 30`;\n\n  files['.gitignore'] = `.gradle/\nbuild/\n.idea/\nlocal.properties\n*.iml\ncaptures/`;\n\n  return files;\n}\n\nfunction resizeIcon(dataUrl, size) {\n  return new Promise((resolve) => {\n    const img = new Image();\n    img.onload = () => {\n      const canvas = document.createElement('canvas');\n      canvas.width = size;\n      canvas.height = size;\n      const ctx = canvas.getContext('2d');\n      ctx.drawImage(img, 0, 0, size, size);\n      resolve(canvas.toDataURL('image/png'));\n    };\n    img.onerror = () => resolve(dataUrl);\n    img.src = dataUrl;\n  });\n}\n\nfunction generatePlainIcon(size, bg, label) {\n  return new Promise((resolve) => {\n    const canvas = document.createElement('canvas');\n    canvas.width = size;\n    canvas.height = size;\n    const ctx = canvas.getContext('2d');\n    ctx.fillStyle = bg || '#000000';\n    ctx.fillRect(0, 0, size, size);\n    const letter = (label || 'A').trim().charAt(0).toUpperCase();\n    ctx.fillStyle = isLight(bg) ? '#000000' : '#ffffff';\n    ctx.font = `bold ${size * 0.55}px -apple-system, sans-serif`;\n    ctx.textAlign = 'center';\n    ctx.textBaseline = 'middle';\n    ctx.fillText(letter, size / 2, size / 2 + size * 0.03);\n    resolve(canvas.toDataURL('image/png'));\n  });\n}\n\n/* ════════════════");
        sb.append("═══════════════════════════════════════════════\n   GITHUB API\n   ═══════════════════════════════════════════════════════════════ */\nasync function gh(method, path, body, _attempt = 0) {\n  const res = await fetch('https://api.github.com' + path, {\n    method,\n    headers: {\n      Authorization: 'token ' + state.gh.token,\n      Accept: 'application/vnd.github+json',\n      'Content-Type': 'application/json',\n    },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const text = await res.text();\n  let json;\n  try { json = text ? JSON.parse(text) : null; } catch { json = { raw: text }; }\n\n  if ((res.status === 409 || res.status >= 500) && _attempt < 3) {\n    await new Promise(r => setTimeout(r, 1500 * (_attempt + 1)));\n    return gh(method, path, body, _attempt + 1);\n  }\n\n  if (!res.ok) {\n    const msg = json?.message || text || 'неизвестная ошибка';\n    const errors = json?.errors || [];\n    const details = errors.map(e => e.message || JSON.stringify(e)).join('; ');\n    let hint = '';\n    if (res.status === 401) hint = ' — токен недействителен';\n    else if (res.status === 403) hint = ' — нет прав';\n    else if (res.status === 404) hint = ' — не найдено';\n    else if (res.status === 409) hint = ' — конфликт состояния';\n    else if (res.status === 422) hint = ' — ' + (details || 'неверные параметры');\n    else if (res.status === 429) hint = ' — слишком много запросов';\n    const err = new Error(`[${res.status}] ${msg}${hint}`);\n    err.status = res.status;\n    throw err;\n  }\n  return json;\n}\n\n/* ═══════════════════════════════════════════════════════════════\n   BUILD FLOW\n   ═══════════════════════════════════════════════════════════════ */\nlet buildInProgress = false;\n\nasync function startBuild() {\n  if (buildInProgress) {\n    flashMessage('Сборка уже идёт');\n    showView('terminal');\n    return;\n  }\n  buildInProgress = true;\n\n  showView('terminal');\n  terminal.clear();\n  terminal.autoScroll = true;\n  $('term_info').textContent = 'Сборка запущена...';\n  $('btnBuildTop').disabled = true;\n\n  const user = state.gh.user;\n  const repo = sanitizeRepoName(state.gh.repo);\n  let run = null;\n\n  const log = (msg, cls = '') => terminal.write(msg, cls);\n\n  try {\n    log('Проверка репозитория ' + user + '/' + repo + '...', 'info');\n    let exists = true;\n    try {\n      await gh('GET', `/repos/${user}/${repo}`);\n      log('Репозиторий найден', 'ok');\n    } catch (e) {\n      if (e.status === 404) {\n        exists = false;\n        log('Создаю репозиторий...', 'info');\n        try {\n          await gh('POST', '/user/repos', { name: repo, private: false, auto_init: false });\n          await new Promise(r => setTimeout(r, 2000));\n          log('Репозиторий создан', 'ok');\n        } catch (createErr) {\n          if (createErr.status === 422 && /already exists/i.test(createErr.message)) {\n            log('Репозиторий уже существует', 'info');\n            exists = true;\n          } else throw createErr;\n        }\n      } else throw e;\n    }\n\n    // Проверка paren");
        sb.append("t SHA\n    let parentSha = null;\n    async function tryGetParent() {\n      try {\n        const ref = await gh('GET', `/repos/${user}/${repo}/git/ref/heads/main`);\n        return ref.object.sha;\n      } catch (e) {\n        if (e.status === 404 || e.status === 409) {\n          try {\n            const ref2 = await gh('GET', `/repos/${user}/${repo}/git/ref/heads/master`);\n            return ref2.object.sha;\n          } catch { return null; }\n        }\n        throw e;\n      }\n    }\n\n    for (let attempt = 0; attempt < 3; attempt++) {\n      parentSha = await tryGetParent();\n      if (parentSha) break;\n      if (attempt < 2) await new Promise(r => setTimeout(r, 1500));\n    }\n\n    log('Состояние: ' + (parentSha ? 'есть коммиты' : 'пустой репозиторий'), 'dim');\n\n    log('Генерация файлов проекта...', 'info');\n    const files = await buildProjectFiles();\n\n    // Повторная проверка\n    if (!parentSha) {\n      try {\n        const ref = await gh('GET', `/repos/${user}/${repo}/git/ref/heads/main`);\n        if (ref && ref.object && ref.object.sha) {\n          parentSha = ref.object.sha;\n          log('Репозиторий инициализирован — Git Data API', 'info');\n        }\n      } catch {}\n    }\n\n    if (!parentSha) {\n      log('Первый коммит через Contents API...', 'info');\n      const entries = Object.entries(files);\n      let firstFileDone = false;\n\n      for (const [path, content] of entries) {\n        let base64Content;\n        if (content instanceof Uint8Array) {\n          let binary = '';\n          for (let i = 0; i < content.length; i++) binary += String.fromCharCode(content[i]);\n          base64Content = btoa(binary);\n        } else {\n          base64Content = utf8ToBase64(content);\n        }\n\n        const apiPath = encodeURIComponent(path).replace(/%2F/g, '/');\n        const body = {\n          message: firstFileDone ? 'Add ' + path : 'Initial commit',\n          content: base64Content,\n          branch: 'main',\n        };\n\n        const MAX_TRIES = 5;\n        let uploaded = false;\n        let lastErr = null;\n\n        for (let attempt = 0; attempt < MAX_TRIES && !uploaded; attempt++) {\n          try {\n            await gh('PUT', `/repos/${user}/${repo}/contents/${apiPath}`, body);\n            uploaded = true;\n            firstFileDone = true;\n            log('  + ' + path, 'ok');\n          } catch (fileErr) {\n            lastErr = fileErr;\n\n            if (fileErr.status === 409) {\n              log('    задержка (409), повтор...', 'warn');\n              await new Promise(r => setTimeout(r, 2000));\n              try {\n                const ref = await gh('GET', `/repos/${user}/${repo}/git/ref/heads/main`);\n                if (ref && ref.object && ref.object.sha) {\n                  parentSha = ref.object.sha;\n                  log('    репо готов, переключение на Git Data API', 'info');\n                  break;\n                }\n              } catch {}\n              continue;\n            }\n\n            if (fileErr.status === 422) {\n              try {\n        ");
