        sb.append(" for (let i = 0; i < 20; i++) {\n        await new Promise(r => setTimeout(r, 3000));\n        try {\n          const runs = await gh('GET', `/repos/${user}/${repo}/actions/runs?per_page=5`);\n          const c = lastSha\n            ? runs.workflow_runs.find(r => r.head_sha === lastSha)\n            : runs.workflow_runs[0];\n          if (c) { run = c; break; }\n        } catch {}\n      }\n    }\n\n    if (!run) throw new Error('Workflow не запустился. Проверьте вкладку Actions.');\n    log('Workflow #' + run.run_number + ' запущен', 'ok');\n    $('term_info').textContent = 'Сборка #' + run.run_number;\n\n    log('Ожидание сборки APK...', 'info');\n    const start = Date.now();\n    while (Date.now() - start < 10 * 60 * 1000) {\n      await new Promise(r => setTimeout(r, 8000));\n      const r = await gh('GET', `/repos/${user}/${repo}/actions/runs/${run.id}`);\n      const elapsed = Math.floor((Date.now() - start) / 1000);\n      log('  ... ' + elapsed + 'с (' + r.status + ')', 'dim');\n\n      if (r.status === 'completed') {\n        if (r.conclusion !== 'success') {\n          log('Сборка провалена. Загрузка логов...', 'err');\n          try {\n            const jobs = await gh('GET', `/repos/${user}/${repo}/actions/runs/${run.id}/jobs`);\n            for (const job of jobs.jobs) {\n              if (job.conclusion === 'failure') {\n                for (const step of job.steps) {\n                  if (step.conclusion === 'failure') {\n                    log('Упавший шаг: ' + step.name, 'err');\n                  }\n                }\n                const logRes = await fetch(\n                  `https://api.github.com/repos/${user}/${repo}/actions/jobs/${job.id}/logs`,\n                  { headers: { Authorization: 'token ' + state.gh.token } }\n                );\n                if (logRes.ok) {\n                  const logText = await logRes.text();\n                  const lines = logText.split('\\n');\n                  const tail = lines.slice(-60).join('\\n');\n                  log('---- последние 60 строк ----', 'warn');\n                  terminal.write(tail, 'dim');\n                }\n              }\n            }\n          } catch (logErr) {\n            log('Не удалось загрузить логи: ' + logErr.message, 'err');\n          }\n          throw new Error('Сборка провалена: ' + r.html_url);\n        }\n        run = r;\n        break;\n      }\n    }\n    if (run.status !== 'completed') throw new Error('Таймаут ожидания');\n    log('Сборка завершена успешно', 'ok');\n\n    log('Скачивание APK...', 'info');\n    const arts = await gh('GET', `/repos/${user}/${repo}/actions/runs/${run.id}/artifacts`);\n    const apkArt = arts.artifacts.find(a => a.name.includes('app-debug'));\n    if (!apkArt) throw new Error('Артефакт не найден');\n\n    const dl = await fetch(apkArt.archive_download_url, {\n      headers: { Authorization: 'token ' + state.gh.token },\n    });\n    const blob = await dl.blob();\n    const zip = await JSZip.loadAsync(blob);\n    const apkEntry = Object.values(zip.files).find(f => f.nam");
        sb.append("e.endsWith('.apk'));\n    if (!apkEntry) throw new Error('APK не найден');\n    const apkBlob = await apkEntry.async('blob');\n\n    const fileName = (state.project.name || 'app').replace(/[^a-zA-Z0-9]/g, '_').toLowerCase() + '.apk';\n    downloadBlob(apkBlob, fileName);\n    log('APK сохранён: ' + fileName, 'ok');\n    log('Размер: ' + (apkBlob.size / 1024).toFixed(1) + ' КБ', 'dim');\n    $('term_info').textContent = 'Готово: ' + fileName;\n  } catch (e) {\n    log('ОШИБКА: ' + e.message, 'err');\n    $('term_info').textContent = 'Ошибка сборки';\n  } finally {\n    buildInProgress = false;\n    $('btnBuildTop').disabled = false;\n  }\n}\n\n$('btnBuildTop').addEventListener('click', startBuild);\n\n/* ═══════════════════════════════════════════════════════════════\n   INIT\n   ═══════════════════════════════════════════════════════════════ */\n(async () => {\n  // Загружаем последний проект или создаём новый\n  try {\n    const lastId = PM.getCurrentId();\n    if (lastId) {\n      const proj = await PM.get(lastId);\n      if (proj) applyProject(proj);\n    }\n  } catch (e) {\n    console.warn('init error', e);\n  }\n\n  // Если ничего не загрузилось — стартовые значения\n  if (!currentProjectId) {\n    $('customCode').value = '';\n    codeArea.value = '';\n    updateIconPreview();\n    updateStatus();\n    refreshFileManagerUI();\n    await autoSaveProject();\n  }\n\n  startAutoSave();\n\n  // Сохранение при уходе\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'hidden') autoSaveProject();\n  });\n  window.addEventListener('pagehide', () => autoSaveProject());\n  window.addEventListener('beforeunload', () => autoSaveProject());\n\n  document.addEventListener('gesturestart', e => e.preventDefault());\n\n  terminal.write('$ APK Builder готов', 'ok');\n  terminal.write('$ Хранилище: ' + STORAGE.label, 'dim');\n  terminal.write('$ Проектов: ' + PM.list().length, 'dim');\n  terminal.write('$ Нажмите «Собрать» для запуска', 'dim');\n})();\n</script>\n</body>\n</html>");
